#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <fstream>
#include <iostream>
using namespace fedspatial;
static Matrix load(const char* p){std::ifstream f(p);int r,c;if(!(f>>r>>c))throw std::runtime_error("missing fixture");Matrix x(r,c);for(double&v:x.a)f>>v;return x;}
static WorkerInput fixture(int n){auto a=load("sync_gpu/tests/fixtures/figure1_reference/worker_0.txt");Matrix s(n,2),z(n,1),x(n,5);for(int i=0;i<n;++i){s(i,0)=a(i,0);s(i,1)=a(i,1);z(i,0)=a(i,2);for(int j=0;j<5;++j)x(i,j)=a(i,j+3);}return{s,z,x};}
static bool run(int n){auto k=load("sync_gpu/tests/fixtures/figure1_reference/knots.txt");GlobalParameters p{load("sync_gpu/tests/fixtures/figure1_reference/p_initial_gamma_new.txt"),load("sync_gpu/tests/fixtures/figure1_reference/p_initial_global_mu.txt"),load("sync_gpu/tests/fixtures/figure1_reference/p_initial_global_sigma.txt"),.25,1.,.11};GpuContext c(0);auto w=fixture(n);auto state=build_device_mu_sigma_local(c,w,k,p);auto fixed=build_device_delta_theta_workspace(c,state);auto h=download_device_delta_theta_workspace_for_test(c,fixed);auto local=download_device_mu_sigma_local(c,state);double q=0,t=0,trw=0,uu=0,ld=-n*std::log(p.delta);for(int i=0;i<n;++i){q+=h.r(i,0)*h.u(i,0);trw+=h.W(i,i);uu+=h.u(i,0)*h.u(i,0);ld+=2*std::log(local.chol_M(i,i));for(int j=0;j<n;++j)t+=h.W(i,j)*h.Q(j,i);}auto wb=matmul(h.W,local.B);auto gram=matmul(transpose(wb),wb);double vv=0;for(int i=0;i<gram.rows;++i)for(int j=0;j<gram.cols;++j)vv+=gram(i,j)*p.sigma(j,i);DeviceDeltaThetaDeltaFirstReduction ref{ld+p.delta*(q+t),-trw/p.delta+uu+vv};auto before_h2d=c.raw_h2d_bytes(),before_d2h=c.result_d2h_bytes();auto a=compute_device_delta_theta_delta_first_reduction_streamed(c,w,k,p);auto mid_h2d=c.raw_h2d_bytes();auto b=compute_device_delta_theta_delta_first_reduction_streamed(c,w,k,p);double ae=std::max(std::abs(a.objective-ref.objective),std::abs(a.delta_gradient-ref.delta_gradient));double re=ae/std::max({1.,std::abs(ref.objective),std::abs(ref.delta_gradient)});bool repeat=std::memcmp(&a,&b,sizeof(a))==0, stationary=mid_h2d==c.raw_h2d_bytes();std::cout<<"STREAM_DELTA_FIRST_N="<<n<<" MAX_ABS="<<ae<<" MAX_REL="<<re<<" EXACT_REPEAT="<<(repeat?"PASS":"FAIL")<<" ACTIVE_H2D_BYTES="<<(c.raw_h2d_bytes()-before_h2d)<<" ACTIVE_D2H_BYTES="<<(c.result_d2h_bytes()-before_d2h)<<" ZERO_REPEAT_H2D="<<(stationary?"PASS":"FAIL")<<'\n';return ae<=1e-10&&re<=1e-10&&repeat&&stationary;}
int main(){try{bool ok=run(3)&&run(100);std::cout<<"STREAMED_DELTA_FIRST_PARITY="<<(ok?"PASS":"FAIL")<<'\n';return ok?0:1;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
